import { useCallback, useEffect, useMemo, useState } from 'react'
import type React from 'react'
import { Link, Navigate, Route, Routes, useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom'
import { BarChart3, Bot, Check, ChevronRight, ClipboardList, Heart, Home, LayoutDashboard, Loader2, LogIn, Menu, Moon, Package, Search, ShieldCheck, ShoppingBag, SlidersHorizontal, Sparkles, Sun, Truck, UserRound, Users, X } from 'lucide-react'
import type { Address, GenMBUser } from './types/genmb'
import type { Product } from './data/products'
import { Button, EmptyState, Field, Modal, ProductCard, SelectField, Stars, ToastViewport, type Toast } from './components/ui'
import { money, salePrice, dateLabel, cn } from './lib/utils'
import { ensureProfile, getCart, getCoupon, getProduct, getWishlist, listAddresses, listConversation, listOrders, listProducts, listProfiles, listReviews, removeProduct, saveAddress, saveCart, saveConversation, saveOrder, saveProduct, saveProfile, saveReview, saveWishlist, updateOrder, type Cart, type Coupon, type Order, type OrderStatus, type UserProfile } from './lib/store'
import { runAgent } from './lib/agent'
import { ComparePage, DashboardPage, RecommendationsPage } from './components/commerce-pages'

const ADMIN_EMAIL = 'admin@growthgenie.ai'
const initialAddress: Address = { line1:'', line2:'', city:'', region:'', postalCode:'', country:'United States', countryCode:'US' }

type AppContext = { user: GenMBUser | null; profile: UserProfile | null; catalog: Product[]; cart: Cart; wishlist: string[]; loading: boolean; refreshCatalog: () => Promise<void>; addToCart: (product: Product, quantity?: number) => Promise<void>; toggleWish: (product: Product) => Promise<void>; notify: (type: Toast['type'], title: string, description?: string) => void; refreshCart: () => Promise<void>; updateProfile: (profile: UserProfile) => void }

function useDocument(title: string, description: string) { useEffect(() => { document.title = title; document.querySelector('meta[name="description"]')?.setAttribute('content', description) }, [title, description]) }

function App() {
  const [user, setUser] = useState<GenMBUser | null>(null)
  const [profile, setProfile] = useState<UserProfile | null>(null)
  const [catalog, setCatalog] = useState<Product[]>([])
  const [cart, setCart] = useState<Cart>({ items: [] })
  const [wishlist, setWishlist] = useState<string[]>([])
  const [loading, setLoading] = useState(true)
  const [toasts, setToasts] = useState<Toast[]>([])
  const notify = useCallback((type: Toast['type'], title: string, description?: string) => { const id = crypto.randomUUID(); setToasts((items) => [...items, { id, type, title, description }]); window.setTimeout(() => setToasts((items) => items.filter((item) => item.id !== id)), 4500) }, [])
  const refreshCatalog = useCallback(async () => { try { setCatalog(await listProducts()) } catch (err: any) { notify('error', 'Could not load the catalog', err?.message) } }, [notify])
  const refreshCart = useCallback(async () => { if (!user) { setCart({ items: [] }); setWishlist([]); return } try { const [nextCart, nextWishlist] = await Promise.all([getCart(user.id), getWishlist(user.id)]); setCart(nextCart); setWishlist(nextWishlist) } catch (err: any) { notify('error', 'Could not load saved shopping items', err?.message) } }, [user, notify])
  useEffect(() => { let mounted = true; const boot = async () => { try { await window.genmb.auth.ready(); const current = window.genmb.auth.getUser(); if (!mounted) return; setUser(current); if (current) setProfile(await ensureProfile(current)); await refreshCatalog(); if (current) { const [nextCart, nextWishlist] = await Promise.all([getCart(current.id), getWishlist(current.id)]); if (mounted) { setCart(nextCart); setWishlist(nextWishlist) } } } catch (err: any) { notify('error', 'GrowthGenie could not start', err?.message) } finally { if (mounted) setLoading(false) } }; void boot(); return window.genmb.auth.onAuthStateChange((nextUser) => { setUser(nextUser); if (!nextUser) { setProfile(null); setCart({ items: [] }); setWishlist([]); return } void ensureProfile(nextUser).then(setProfile).catch((err: any) => notify('error','Could not load your profile',err?.message)); void refreshCart() }) }, [notify, refreshCatalog, refreshCart])
  const addToCart = useCallback(async (product: Product, quantity = 1) => { if (!user) { notify('info', 'Sign in to build your cart', 'Your cart is saved securely to your account.'); return } if (product.stock < quantity) { notify('error', 'Not enough stock', `${product.name} has only ${product.stock} remaining.`); return } try { const current = await getCart(user.id); const existing = current.items.find((item) => item.productId === product.id); const next: Cart = { ...current, items: existing ? current.items.map((item) => item.productId === product.id ? { ...item, quantity: Math.min(item.quantity + quantity, product.stock) } : item) : [...current.items, { productId: product.id, quantity }] }; await saveCart(user.id, next); setCart(next); try { await window.genmb.commerce.addToCart(product.id, quantity) } catch (commerceError: any) { notify('info', 'Saved to your GrowthGenie cart', commerceError?.message) }; notify('success', 'Added to your cart', product.name) } catch (err: any) { notify('error', 'Could not update cart', err?.message) } }, [user, notify])
  const toggleWish = useCallback(async (product: Product) => { if (!user) { notify('info','Sign in to save favorites','Wishlist items are available on every device after you sign in.'); return } try { const current = await getWishlist(user.id); const next = current.includes(product.id) ? current.filter((id) => id !== product.id) : [...current, product.id]; await saveWishlist(user.id, next); setWishlist(next); notify('success', current.includes(product.id) ? 'Removed from wishlist' : 'Saved to wishlist', product.name) } catch (err: any) { notify('error','Could not update wishlist',err?.message) } }, [user, notify])
  const context: AppContext = { user, profile, catalog, cart, wishlist, loading, refreshCatalog, addToCart, toggleWish, notify, refreshCart, updateProfile: setProfile }
  return <><Routes><Route path="/" element={<HomePage ctx={context} />} /><Route path="/shop" element={<ShopPage ctx={context} />} /><Route path="/products" element={<ShopPage ctx={context} />} /><Route path="/product/:id" element={<ProductPage ctx={context} />} /><Route path="/agent" element={<AgentPage ctx={context} />} /><Route path="/compare" element={<ComparePage ctx={context} />} /><Route path="/recommendations" element={<RecommendationsPage ctx={context} />} /><Route path="/dashboard" element={<DashboardPage ctx={context} />} /><Route path="/cart" element={<CartPage ctx={context} />} /><Route path="/wishlist" element={<WishlistPage ctx={context} />} /><Route path="/checkout" element={<CheckoutPage ctx={context} />} /><Route path="/orders" element={<OrdersPage ctx={context} />} /><Route path="/orders/:id" element={<OrderDetailPage ctx={context} />} /><Route path="/profile" element={<ProfilePage ctx={context} />} /><Route path="/login" element={<LoginPage ctx={context} />} /><Route path="/admin" element={<AdminPage ctx={context} />} /><Route path="*" element={<Navigate to="/" replace />} /></Routes><ToastViewport toasts={toasts} onDismiss={(id) => setToasts((items) => items.filter((item) => item.id !== id))} /></>
}

function Shell({ ctx, children }: { ctx: AppContext; children: React.ReactNode }) {
  const [menuOpen, setMenuOpen] = useState(false); const [dark, setDark] = useState(() => localStorage.getItem('growthgenie-theme') === 'dark'); const location = useLocation(); const navigate = useNavigate(); useEffect(() => { document.documentElement.classList.toggle('dark', dark); localStorage.setItem('growthgenie-theme', dark ? 'dark' : 'light') }, [dark])
  const nav = [{to:'/products',label:'Products',icon:ShoppingBag},{to:'/agent',label:'AI Agent',icon:Bot},{to:'/compare',label:'Compare',icon:BarChart3},{to:'/recommendations',label:'AI Picks',icon:Sparkles},{to:'/wishlist',label:'Wishlist',icon:Heart},{to:'/orders',label:'Orders',icon:ClipboardList},{to:'/dashboard',label:'Dashboard',icon:LayoutDashboard}]
  const cartCount = ctx.cart.items.reduce((sum,item) => sum + item.quantity,0)
  const signOut = async () => { try { await window.genmb.auth.signOut(); ctx.notify('success','Signed out securely'); navigate('/') } catch (err: any) { ctx.notify('error','Could not sign out',err?.message) } }
  return <div className="min-h-screen"><header className="sticky top-0 z-30 border-b bg-background/95 backdrop-blur"><div className="mx-auto flex h-16 max-w-7xl items-center justify-between gap-3 px-4 sm:px-6"><Link to="/" className="flex items-center gap-2 font-bold tracking-tight"><span className="grid size-9 place-items-center rounded-lg bg-primary text-primary-foreground"><Sparkles size={18}/></span><span>Growth<span className="text-primary">Genie</span></span></Link><nav aria-label="Primary" className="hidden items-center gap-1 md:flex">{nav.map(({to,label,icon:Icon}) => <Link key={to} to={to} className={cn('inline-flex items-center gap-2 rounded-lg px-3 py-2 text-sm font-medium transition hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring', location.pathname === to || (to === '/products' && (location.pathname.startsWith('/product') || location.pathname === '/shop')) ? 'bg-accent text-primary' : 'text-muted-foreground')}><Icon size={16}/>{label}</Link>)}</nav><div className="flex items-center gap-1"><button onClick={() => setDark(value => !value)} aria-label="Toggle color theme" className="rounded-lg p-2 hover:bg-accent">{dark ? <Sun size={18}/> : <Moon size={18}/>}</button><Link to="/cart" aria-label={`Cart, ${cartCount} items`} className="relative rounded-lg p-2 hover:bg-accent"><ShoppingBag size={19}/>{cartCount > 0 && <span className="absolute -right-1 -top-1 grid min-w-5 place-items-center rounded-full bg-primary px-1 text-xs font-bold text-primary-foreground">{cartCount}</span>}</Link>{ctx.profile?.role === 'admin' && <Link to="/admin" aria-label="Admin dashboard" className="rounded-lg p-2 text-primary hover:bg-accent"><ShieldCheck size={19}/></Link>}{ctx.user ? <button onClick={signOut} className="hidden rounded-lg px-3 py-2 text-sm font-semibold hover:bg-accent sm:inline-flex">Sign out</button> : <Link to="/login" className="hidden rounded-lg bg-primary px-3 py-2 text-sm font-semibold text-primary-foreground transition hover:-translate-y-0.5 hover:shadow-md sm:inline-flex">Sign in</Link>}<button aria-label="Toggle menu" onClick={() => setMenuOpen(!menuOpen)} className="rounded-lg p-2 hover:bg-accent md:hidden">{menuOpen ? <X size={20}/> : <Menu size={20}/>}</button></div></div>{menuOpen && <nav aria-label="Mobile" className="fade-in border-t bg-popover p-3 md:hidden">{nav.map(({to,label,icon:Icon}) => <Link key={to} onClick={() => setMenuOpen(false)} to={to} className="flex items-center gap-3 rounded-lg px-3 py-3 hover:bg-accent"><Icon size={17}/>{label}</Link>)}<Link onClick={() => setMenuOpen(false)} to={ctx.user ? '/profile' : '/login'} className="flex items-center gap-3 rounded-lg px-3 py-3 hover:bg-accent"><UserRound size={17}/>{ctx.user ? 'Profile' : 'Sign in'}</Link></nav>}</header><main>{children}</main><footer className="mt-16 border-t"><div className="mx-auto flex max-w-7xl flex-col gap-2 px-4 py-8 text-sm text-muted-foreground sm:flex-row sm:items-center sm:justify-between sm:px-6"><p>© 2026 GrowthGenie AI. Thoughtful shopping, intelligently guided.</p><p>Secure account, payment, address, and data services powered by GenMB.</p></div></footer></div>
}

function HomePage({ctx}:{ctx:AppContext}) { useDocument('GrowthGenie AI | Agentic Commerce Platform','Discover, compare, and buy products with an AI shopping concierge tailored to your goals.'); const highlights = ctx.catalog.slice(0,4); return <Shell ctx={ctx}><section className="border-b bg-[radial-gradient(ellipse_at_top_left,var(--accent),transparent_55%)]"><div className="mx-auto grid max-w-7xl gap-10 px-4 py-16 sm:px-6 lg:grid-cols-[1.1fr_.9fr] lg:py-24"><div className="max-w-2xl"><p className="mb-4 inline-flex items-center gap-2 rounded-full border bg-card px-3 py-1 text-sm font-semibold text-primary"><Sparkles size={15}/> Agentic commerce, made human</p><h1 className="text-4xl font-black tracking-tight sm:text-6xl">Your personal shopper for better decisions.</h1><p className="mt-6 max-w-xl text-lg leading-8 text-muted-foreground">Tell GrowthGenie what you need. Our AI concierge searches the catalog, weighs price, ratings, fit, and value, then helps you check out with confidence.</p><div className="mt-8 flex flex-wrap gap-3"><Link to="/agent"><Button><Bot size={17}/> Shop with AI</Button></Link><Link to="/shop"><Button variant="outline">Browse catalog <ChevronRight size={17}/></Button></Link></div><div className="mt-10 grid grid-cols-3 gap-4 border-t pt-6 text-sm"><div><p className="text-2xl font-bold">20+</p><p className="text-muted-foreground">Curated products</p></div><div><p className="text-2xl font-bold">7</p><p className="text-muted-foreground">Shop categories</p></div><div><p className="text-2xl font-bold">1:1</p><p className="text-muted-foreground">AI guidance</p></div></div></div><div className="grid grid-cols-2 gap-3 self-center">{highlights.map((p) => <div key={p.id} className="overflow-hidden rounded-lg border bg-card p-3 shadow-sm"><img data-genmb-img={p.name} src={p.image} alt={p.name} width="400" height="400" className="aspect-square w-full rounded-md object-cover bg-muted" onError={(event)=>{event.currentTarget.src=`https://picsum.photos/seed/${p.id}-fallback/400/400`}}/><p className="mt-3 line-clamp-1 font-semibold">{p.name}</p><p className="mt-1 text-sm text-primary">{money(salePrice(p.price,p.discount))}</p></div>)}</div></div></section><section className="mx-auto max-w-7xl px-4 py-16 sm:px-6"><div className="mb-8 flex items-end justify-between gap-4"><div><p className="text-sm font-semibold uppercase tracking-[.14em] text-primary">Trending now</p><h2 className="mt-2 text-3xl font-bold">Worth a closer look</h2></div><Link to="/shop" className="text-sm font-semibold text-primary hover:underline">See everything</Link></div>{ctx.loading ? <ProductSkeleton /> : <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{highlights.map((p)=><ProductCard key={p.id} product={p} onAdd={ctx.addToCart} onWish={ctx.toggleWish} wishlisted={ctx.wishlist.includes(p.id)}/>)}</div>}</section><section className="mx-auto grid max-w-7xl gap-5 px-4 pb-4 sm:grid-cols-3 sm:px-6"><InfoCard icon={<Search/>} title="Search with intent" text="Describe the use case, your budget, and what matters most."/><InfoCard icon={<BarChart3/>} title="Compare value" text="See price, ratings, stock, discounts, and best-fit alternatives together."/><InfoCard icon={<Truck/>} title="Move to checkout" text="Save favorites, manage your cart, validate an address, and pay securely."/></section></Shell> }
function InfoCard({icon,title,text}:{icon:React.ReactNode;title:string;text:string}) { return <article className="rounded-lg border bg-card p-6 text-card-foreground shadow-sm"><div className="mb-4 inline-flex rounded-lg bg-accent p-3 text-primary">{icon}</div><h3 className="font-bold">{title}</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{text}</p></article> }
function ProductSkeleton(){ return <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{[1,2,3,4].map((id)=><div key={id} className="rounded-lg border bg-card p-4"><div className="aspect-square animate-pulse rounded-md bg-muted"/><div className="mt-4 h-4 w-2/3 animate-pulse rounded bg-muted"/><div className="mt-3 h-4 w-1/3 animate-pulse rounded bg-muted"/></div>)}</div> }

function ShopPage({ctx}:{ctx:AppContext}) { useDocument('Shop Products | GrowthGenie AI','Search and filter products across electronics, fashion, beauty, home, sports, and more.'); const [search,setSearch]=useState(''); const [category,setCategory]=useState('All'); const [brand,setBrand]=useState('All'); const [minRating,setMinRating]=useState('0'); const [maxPrice,setMaxPrice]=useState('1000'); const [discountOnly,setDiscountOnly]=useState(false); const [sort,setSort]=useState('popularity'); const categories=useMemo(()=>['All',...Array.from(new Set(ctx.catalog.map(p=>p.category)))],[ctx.catalog]); const brands=useMemo(()=>['All',...Array.from(new Set(ctx.catalog.map(p=>p.brand)))],[ctx.catalog]); const results=useMemo(()=>ctx.catalog.filter((p)=>{const needle=search.toLowerCase(); return (!needle || [p.name,p.brand,p.description,...p.tags].join(' ').toLowerCase().includes(needle)) && (category==='All'||p.category===category) && (brand==='All'||p.brand===brand) && p.rating>=Number(minRating) && salePrice(p.price,p.discount)<=Number(maxPrice) && (!discountOnly||p.discount>0)}).sort((a,b)=>sort==='price-low'?salePrice(a.price,a.discount)-salePrice(b.price,b.discount):sort==='price-high'?salePrice(b.price,b.discount)-salePrice(a.price,a.discount):sort==='rating'?b.rating-a.rating:sort==='newest'?Date.parse(b.createdAt)-Date.parse(a.createdAt):b.popularity-a.popularity),[ctx.catalog,search,category,brand,minRating,maxPrice,discountOnly,sort]); const clear=()=>{setSearch('');setCategory('All');setBrand('All');setMinRating('0');setMaxPrice('1000');setDiscountOnly(false);setSort('popularity')}; return <Shell ctx={ctx}><section className="mx-auto max-w-7xl px-4 py-10 sm:px-6"><div className="mb-8"><p className="text-sm font-semibold uppercase tracking-[.14em] text-primary">The catalog</p><h1 className="mt-2 text-4xl font-bold">Find your next favorite</h1><p className="mt-3 text-muted-foreground">Search, compare, and filter products by what matters to you.</p></div><div className="grid gap-6 lg:grid-cols-[260px_1fr]"><aside className="h-fit rounded-lg border bg-card p-5 shadow-sm"><div className="mb-4 flex items-center justify-between"><h2 className="font-bold">Filters</h2><SlidersHorizontal size={17} className="text-muted-foreground"/></div><div className="grid gap-4"><Field label="Search products" value={search} onChange={(e)=>setSearch(e.target.value)} placeholder="Headphones, yoga, leather…"/><SelectField label="Category" value={category} onChange={(e)=>setCategory(e.target.value)}><>{categories.map((item)=><option key={item}>{item}</option>)}</></SelectField><SelectField label="Brand" value={brand} onChange={(e)=>setBrand(e.target.value)}><>{brands.map((item)=><option key={item}>{item}</option>)}</></SelectField><SelectField label="Minimum rating" value={minRating} onChange={(e)=>setMinRating(e.target.value)}><option value="0">Any rating</option><option value="4.5">4.5+ stars</option><option value="4.7">4.7+ stars</option><option value="4.8">4.8+ stars</option></SelectField><Field label="Maximum sale price" type="number" min="1" value={maxPrice} onChange={(e)=>setMaxPrice(e.target.value)}/><label className="flex cursor-pointer items-center gap-2 text-sm font-medium"><input type="checkbox" checked={discountOnly} onChange={(e)=>setDiscountOnly(e.target.checked)} className="size-4 accent-[var(--primary)]"/> On sale only</label><Button variant="ghost" onClick={clear}>Clear filters</Button></div></aside><div><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-muted-foreground"><strong className="text-foreground">{results.length}</strong> products found</p><SelectField label="Sort products" value={sort} onChange={(e)=>setSort(e.target.value)} className="w-52"><option value="popularity">Most popular</option><option value="newest">Newest</option><option value="rating">Highest rated</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option></SelectField></div>{ctx.loading ? <ProductSkeleton/> : results.length ? <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{results.map((p)=><ProductCard key={p.id} product={p} onAdd={ctx.addToCart} onWish={ctx.toggleWish} wishlisted={ctx.wishlist.includes(p.id)}/>)}</div> : <EmptyState icon={<Search size={28}/>} title="No matches found" description="Try clearing a filter or searching for a different category, brand, or feature." action={<Button onClick={clear}>Clear filters</Button>}/>}</div></div></section></Shell> }

function ProductPage({ctx}:{ctx:AppContext}) { const {id=''}=useParams(); const [product,setProduct]=useState<Product|null>(null); const [reviews,setReviews]=useState<any[]>([]); const [loading,setLoading]=useState(true); const [quantity,setQuantity]=useState(1); const [comment,setComment]=useState(''); const [rating,setRating]=useState('5'); useDocument(product ? `${product.name} | GrowthGenie AI` : 'Product details | GrowthGenie AI','Explore product details, ratings, related products, and personalized shopping help.'); useEffect(()=>{void (async()=>{try {const found=ctx.catalog.find(p=>p.id===id) ?? await getProduct(id); setProduct(found); if(found) setReviews(await listReviews(found.id))} catch(err:any){ctx.notify('error','Could not load product',err?.message)} finally{setLoading(false)}})()},[id,ctx.catalog,ctx.notify]); if(loading) return <Shell ctx={ctx}><div className="mx-auto max-w-7xl px-4 py-12 sm:px-6"><ProductSkeleton/></div></Shell>; if(!product) return <Shell ctx={ctx}><div className="mx-auto max-w-7xl px-4 py-12 sm:px-6"><EmptyState title="Product unavailable" description="This product may have been removed from the catalog." action={<Link to="/shop"><Button>Browse products</Button></Link>}/></div></Shell>; const related=ctx.catalog.filter((p)=>p.id!==product.id && (p.category===product.category || p.tags.some(tag=>product.tags.includes(tag)))).slice(0,4); const submitReview=async(e:React.FormEvent)=>{e.preventDefault(); if(!ctx.user){ctx.notify('info','Sign in to leave a review');return} if(comment.trim().length<8){ctx.notify('error','Tell shoppers a little more','Your review needs at least 8 characters.');return} try {const review={id:crypto.randomUUID(),productId:product.id,userId:ctx.user.id,author:ctx.user.name||ctx.user.email,rating:Number(rating),comment:comment.trim(),createdAt:new Date().toISOString()}; await saveReview(review); setReviews((items)=>[review,...items]);setComment('');ctx.notify('success','Review published','Thanks for helping the community.')} catch(err:any){ctx.notify('error','Could not publish review',err?.message)}}; return <Shell ctx={ctx}><section className="mx-auto max-w-7xl px-4 py-10 sm:px-6"><nav aria-label="Breadcrumb" className="mb-6 text-sm text-muted-foreground"><Link to="/shop" className="hover:text-primary">Shop</Link> <span className="px-2">/</span> <span>{product.category}</span></nav><div className="grid gap-8 lg:grid-cols-2"><div className="overflow-hidden rounded-lg border bg-card"><img data-genmb-img={product.name} src={product.image} alt={product.name} width="800" height="800" className="aspect-square w-full object-cover bg-muted" onError={(event)=>{event.currentTarget.src=`https://picsum.photos/seed/${product.id}-fallback/800/800`}}/></div><div><p className="text-sm font-semibold uppercase tracking-[.14em] text-primary">{product.brand} · {product.category}</p><h1 className="mt-2 text-4xl font-bold tracking-tight">{product.name}</h1><div className="mt-4 flex items-center gap-3"><Stars rating={product.rating}/><span className="text-sm text-muted-foreground">{product.reviewCount + reviews.length} reviews</span></div><p className="mt-6 text-lg leading-8 text-muted-foreground">{product.description}</p><div className="mt-6 flex items-baseline gap-3"><p className="text-3xl font-bold">{money(salePrice(product.price,product.discount))}</p>{product.discount>0&&<><p className="text-muted-foreground line-through">{money(product.price)}</p><span className="rounded-full bg-accent px-2 py-1 text-sm font-bold text-primary">Save {product.discount}%</span></>}</div><p className={cn('mt-4 text-sm font-semibold',product.stock?'text-primary':'text-destructive')}>{product.stock ? `${product.stock} in stock · Ready to add` : 'Currently out of stock'}</p><div className="mt-6 flex flex-wrap gap-3"><label className="flex min-h-10 items-center gap-2 rounded-lg border bg-card px-3 text-sm font-medium">Quantity <input aria-label="Quantity" type="number" min="1" max={product.stock} value={quantity} onChange={(e)=>setQuantity(Math.max(1,Math.min(product.stock,Number(e.target.value)||1)))} className="w-12 border-0 bg-transparent text-center outline-none"/></label><Button onClick={()=>ctx.addToCart(product,quantity)} disabled={!product.stock}><ShoppingBag size={17}/> Add to cart</Button><Button variant="outline" onClick={()=>ctx.toggleWish(product)}><Heart size={17} className={ctx.wishlist.includes(product.id)?'fill-current text-destructive':''}/>{ctx.wishlist.includes(product.id)?'Saved':'Save'}</Button></div><div className="mt-8 rounded-lg border bg-muted/60 p-4"><p className="flex items-center gap-2 font-semibold"><Bot size={18} className="text-primary"/> Need a second opinion?</p><p className="mt-1 text-sm text-muted-foreground">Ask the AI concierge to compare this with another product or find a more budget-friendly alternative.</p><Link to="/agent" className="mt-3 inline-block text-sm font-bold text-primary hover:underline">Ask GrowthGenie AI →</Link></div><div className="mt-7 flex flex-wrap gap-2">{product.tags.map((tag)=><span key={tag} className="rounded-full border bg-card px-3 py-1 text-sm text-muted-foreground">{tag}</span>)}</div></div></div></section><section className="mx-auto max-w-7xl px-4 py-12 sm:px-6"><h2 className="text-2xl font-bold">Customer reviews</h2><div className="mt-5 grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><form onSubmit={submitReview} className="rounded-lg border bg-card p-5 shadow-sm"><h3 className="font-bold">Share your experience</h3><div className="mt-4 grid gap-4"><SelectField label="Your rating" value={rating} onChange={(e)=>setRating(e.target.value)}><option value="5">5 — Excellent</option><option value="4">4 — Great</option><option value="3">3 — Good</option><option value="2">2 — Fair</option><option value="1">1 — Poor</option></SelectField><label className="grid gap-1.5 text-sm font-medium">Review<textarea aria-label="Review" value={comment} onChange={(e)=>setComment(e.target.value)} onBlur={()=>comment && comment.trim().length<8 && ctx.notify('info','Add a little more detail','Reviews need at least 8 characters.')} className="min-h-28 rounded-lg border bg-card p-3 text-sm outline-none focus:ring-2 focus:ring-ring" placeholder="What did you like about it?"/></label><Button type="submit">Publish review</Button></div></form><div className="grid gap-3">{reviews.length ? reviews.map((review)=><article key={review.id} className="rounded-lg border bg-card p-5"><div className="flex items-center justify-between gap-3"><p className="font-semibold">{review.author}</p><Stars rating={review.rating}/></div><p className="mt-2 text-sm leading-6 text-muted-foreground">{review.comment}</p><p className="mt-3 text-xs text-muted-foreground">{dateLabel(review.createdAt)}</p></article>) : <EmptyState title="Be the first to review" description="Share your experience and help other shoppers decide."/>}</div></div></section><section className="mx-auto max-w-7xl px-4 pb-4 sm:px-6"><h2 className="mb-5 text-2xl font-bold">You may also like</h2><div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{related.map((p)=><ProductCard key={p.id} product={p} onAdd={ctx.addToCart} onWish={ctx.toggleWish} wishlisted={ctx.wishlist.includes(p.id)}/>)}</div></section></Shell> }

function AgentPage({ctx}:{ctx:AppContext}) { useDocument('AI Shopping Concierge | GrowthGenie AI','Get natural-language shopping recommendations, compare products, and add the right items to your cart.'); const [messages,setMessages]=useState<any[]>([]); const [input,setInput]=useState(''); const [sending,setSending]=useState(false); const [loaded,setLoaded]=useState(false); useEffect(()=>{if(!ctx.user){setLoaded(true);return} void listConversation(ctx.user.id).then((items)=>{setMessages(items);setLoaded(true)}).catch((err:any)=>{ctx.notify('error','Could not load your AI conversation',err?.message);setLoaded(true)})},[ctx.user,ctx.notify]); const send=async(e:React.FormEvent)=>{e.preventDefault();const text=input.trim();if(!text||sending)return;const userMessage={id:crypto.randomUUID(),role:'user' as const,text,createdAt:new Date().toISOString()};setInput('');setSending(true);setMessages((items)=>[...items,userMessage]);try{if(ctx.user)await saveConversation(ctx.user.id,userMessage); const history=messages.map(m=>m.text); const preferenceContext=ctx.profile?.preferences.join(' ') ?? ''; const result=runAgent(`${preferenceContext} ${text}`.trim(),ctx.catalog,history); const agentMessage={id:crypto.randomUUID(),role:'agent' as const,text:result.text,productIds:result.products.map(p=>p.id),createdAt:new Date().toISOString()}; if(ctx.user)await saveConversation(ctx.user.id,agentMessage);setMessages((items)=>[...items,agentMessage])}catch(err:any){ctx.notify('error','The AI concierge could not respond',err?.message)}finally{setSending(false)}}; const recommendationMessage=messages.filter(m=>m.role==='agent'&&m.productIds?.length).slice(-1)[0]; const recommendations=recommendationMessage?.productIds?.map((id:string)=>ctx.catalog.find(p=>p.id===id)).filter(Boolean) as Product[]|undefined; return <Shell ctx={ctx}><section className="mx-auto max-w-7xl px-4 py-10 sm:px-6"><div className="mb-7"><p className="text-sm font-semibold uppercase tracking-[.14em] text-primary">GrowthGenie AI</p><h1 className="mt-2 text-4xl font-bold">Your shopping concierge</h1><p className="mt-3 max-w-2xl text-muted-foreground">Describe what you need in your own words. I’ll rank in-stock products by fit, price, rating, discount, brand, and value, then help you compare and buy.</p></div><div className="grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><section aria-label="AI conversation" className="flex min-h-[560px] flex-col rounded-lg border bg-card shadow-sm"><div className="flex items-center gap-3 border-b p-5"><span className="grid size-10 place-items-center rounded-full bg-primary text-primary-foreground"><Bot size={20}/></span><div><h2 className="font-bold">GrowthGenie Concierge</h2><p className="text-sm text-muted-foreground">Fallback recommendation engine · always available</p></div></div><div className="flex-1 space-y-4 overflow-y-auto p-5">{!loaded ? <div className="space-y-3"><div className="h-16 animate-pulse rounded-lg bg-muted"/><div className="ml-auto h-12 w-3/4 animate-pulse rounded-lg bg-muted"/></div> : messages.length ? messages.map((message)=><div key={message.id} className={cn('max-w-[88%] rounded-lg p-4 text-sm leading-6',message.role==='user'?'ml-auto bg-primary text-primary-foreground':'border bg-muted/50')}><p className="whitespace-pre-line">{message.text}</p></div>) : <div className="flex h-full flex-col justify-center"><p className="text-lg font-semibold">What are you shopping for?</p><p className="mt-1 text-sm text-muted-foreground">Try “I need wireless headphones for travel under $250” or “Compare Aurora X1 and Orbit Pro.”</p><div className="mt-5 flex flex-wrap gap-2">{['Best skincare under $50','A gift for a hiker','Compare Aurora X1 and Orbit Pro'].map((prompt)=><button key={prompt} onClick={()=>setInput(prompt)} className="rounded-full border bg-card px-3 py-2 text-sm font-medium hover:bg-accent">{prompt}</button>)}</div></div>}</div><form onSubmit={send} className="border-t p-4"><label className="sr-only" htmlFor="agent-prompt">Shopping request</label><div className="flex gap-2"><input id="agent-prompt" value={input} onChange={(e)=>setInput(e.target.value)} className="min-h-11 flex-1 rounded-lg border bg-card px-3 text-sm outline-none focus:ring-2 focus:ring-ring" placeholder="Tell the concierge what you need…" disabled={sending}/><Button type="submit" loading={sending} disabled={!input.trim()}><span className="hidden sm:inline">Ask</span><ChevronRight size={17}/></Button></div>{!ctx.user&&<p className="mt-2 text-xs text-muted-foreground">Sign in to save this conversation to your account.</p>}</form></section><aside><h2 className="mb-4 text-xl font-bold">Recommended for you</h2>{recommendations?.length ? <div className="grid gap-4">{recommendations.map((product)=><ProductCard key={product.id} product={product} onAdd={ctx.addToCart} onWish={ctx.toggleWish} wishlisted={ctx.wishlist.includes(product.id)}/>)}</div> : <EmptyState icon={<Sparkles size={28}/>} title="Personalized matches appear here" description="Start a conversation and I’ll show ranked recommendations you can add to your cart." action={<Link to="/shop"><Button variant="outline">Browse products</Button></Link>}/>}</aside></div></section></Shell> }

function CartPage({ctx}:{ctx:AppContext}) { useDocument('Your Cart | GrowthGenie AI','Review your saved cart, manage quantities, apply a coupon, and continue to secure checkout.'); const [coupon,setCoupon]=useState(ctx.cart.couponCode??''); const [applying,setApplying]=useState(false); const items=ctx.cart.items.map(item=>({item,product:ctx.catalog.find(p=>p.id===item.productId)})).filter((entry):entry is {item:{productId:string;quantity:number};product:Product}=>Boolean(entry.product)); const subtotal=items.reduce((sum,{item,product})=>sum+salePrice(product.price,product.discount)*item.quantity,0); const [couponData,setCouponData]=useState<Coupon|null>(null); useEffect(()=>{if(ctx.cart.couponCode)void getCoupon(ctx.cart.couponCode).then(setCouponData)},[ctx.cart.couponCode]); const discount=couponData&&subtotal>=couponData.minSpend?subtotal*couponData.percent/100:0; const update=async(product:Product,quantity:number)=>{if(!ctx.user)return;try{const next={...ctx.cart,items:quantity<=0?ctx.cart.items.filter(i=>i.productId!==product.id):ctx.cart.items.map(i=>i.productId===product.id?{...i,quantity:Math.min(product.stock,quantity)}:i)};await saveCart(ctx.user.id,next);await ctx.refreshCart();ctx.notify('success',quantity<=0?'Removed from cart':'Cart updated',product.name)}catch(err:any){ctx.notify('error','Could not update cart',err?.message)}}; const apply=async()=>{if(!ctx.user)return;setApplying(true);try{const found=await getCoupon(coupon);if(!found){ctx.notify('error','Coupon not found','Check the code and try again.');return}if(subtotal<found.minSpend){ctx.notify('error','Order minimum not reached',`${found.code} applies from ${money(found.minSpend)}.`);return}const next={...ctx.cart,couponCode:found.code};await saveCart(ctx.user.id,next);await ctx.refreshCart();setCouponData(found);ctx.notify('success','Coupon applied',found.label)}catch(err:any){ctx.notify('error','Could not apply coupon',err?.message)}finally{setApplying(false)}}; if(!ctx.user) return <Shell ctx={ctx}><div className="mx-auto max-w-4xl px-4 py-12 sm:px-6"><EmptyState icon={<LogIn size={28}/>} title="Sign in to view your cart" description="Your GrowthGenie cart is saved securely to your account." action={<Link to="/login"><Button>Sign in</Button></Link>}/></div></Shell>; return <Shell ctx={ctx}><section className="mx-auto max-w-6xl px-4 py-10 sm:px-6"><h1 className="text-4xl font-bold">Your cart</h1><p className="mt-2 text-muted-foreground">Manage quantities, save your order, and check out securely.</p>{items.length?<div className="mt-8 grid gap-6 lg:grid-cols-[1fr_340px]"><div className="divide-y rounded-lg border bg-card shadow-sm">{items.map(({item,product})=><article key={product.id} className="flex gap-4 p-4 sm:p-5"><img data-genmb-img={product.name} src={product.image} alt={product.name} width="120" height="120" className="size-24 rounded-md object-cover bg-muted sm:size-28" onError={(event)=>{event.currentTarget.src=`https://picsum.photos/seed/${product.id}-fallback/120/120`}}/><div className="min-w-0 flex-1"><Link to={`/product/${product.id}`} className="font-bold hover:text-primary">{product.name}</Link><p className="mt-1 text-sm text-muted-foreground">{product.brand} · {product.stock} in stock</p><p className="mt-2 font-bold">{money(salePrice(product.price,product.discount))}</p><div className="mt-3 flex flex-wrap items-center gap-3"><div className="inline-flex items-center rounded-lg border"><button onClick={()=>update(product,item.quantity-1)} aria-label={`Decrease ${product.name} quantity`} className="p-2 hover:bg-accent">−</button><span className="min-w-9 text-center text-sm font-semibold">{item.quantity}</span><button onClick={()=>update(product,item.quantity+1)} aria-label={`Increase ${product.name} quantity`} disabled={item.quantity>=product.stock} className="p-2 hover:bg-accent disabled:opacity-50">+</button></div><button onClick={()=>update(product,0)} className="text-sm font-semibold text-destructive hover:underline">Remove</button></div></div><p className="whitespace-nowrap font-bold">{money(salePrice(product.price,product.discount)*item.quantity)}</p></article>)}</div><aside className="h-fit rounded-lg border bg-card p-5 shadow-sm"><h2 className="text-lg font-bold">Order summary</h2><div className="mt-4 grid gap-3 text-sm"><div className="flex justify-between"><span className="text-muted-foreground">Subtotal</span><span>{money(subtotal)}</span></div><div className="flex justify-between"><span className="text-muted-foreground">Discount</span><span className="text-primary">−{money(discount)}</span></div><div className="border-t pt-3 text-base font-bold"><div className="flex justify-between"><span>Total</span><span>{money(subtotal-discount)}</span></div></div></div><div className="mt-5 border-t pt-5"><Field label="Coupon code" value={coupon} onChange={(e)=>setCoupon(e.target.value.toUpperCase())} placeholder="WELCOME10"/><Button className="mt-2 w-full" variant="outline" onClick={apply} loading={applying} disabled={!coupon.trim()}>Apply code</Button>{couponData&&<p className="mt-2 text-xs font-medium text-primary"><Check size={13} className="mr-1 inline"/>{couponData.label}</p>}</div><Link to="/checkout" className="mt-5 block"><Button className="w-full">Secure checkout <ChevronRight size={17}/></Button></Link></aside></div>:<div className="mt-8"><EmptyState icon={<ShoppingBag size={28}/>} title="Your cart is waiting" description="Ask the AI concierge for a recommendation or explore the catalog to add your first product." action={<Link to="/shop"><Button>Explore products</Button></Link>}/></div>}</section></Shell> }

function WishlistPage({ctx}:{ctx:AppContext}) { useDocument('Wishlist | GrowthGenie AI','Keep track of products you love and add them to your secure GrowthGenie cart when ready.'); const products=ctx.catalog.filter(p=>ctx.wishlist.includes(p.id)); return <Shell ctx={ctx}><section className="mx-auto max-w-7xl px-4 py-10 sm:px-6"><h1 className="text-4xl font-bold">Your wishlist</h1><p className="mt-2 text-muted-foreground">Save products you love and return whenever you are ready.</p>{!ctx.user?<div className="mt-8"><EmptyState icon={<Heart size={28}/>} title="Sign in to save favorites" description="Your wishlist follows you across devices once you sign in." action={<Link to="/login"><Button>Sign in</Button></Link>}/></div>:products.length?<div className="mt-8 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{products.map(p=><ProductCard key={p.id} product={p} onAdd={ctx.addToCart} onWish={ctx.toggleWish} wishlisted/>)}</div>:<div className="mt-8"><EmptyState icon={<Heart size={28}/>} title="No saved products yet" description="Explore the catalog and tap the heart to build a shortlist." action={<Link to="/shop"><Button>Explore products</Button></Link>}/></div>}</section></Shell> }

function CheckoutPage({ctx}:{ctx:AppContext}) { useDocument('Secure Checkout | GrowthGenie AI','Validate your delivery address and pay securely for your GrowthGenie order.'); const [addresses,setAddresses]=useState<Array<Address & {id:string}>>([]); const [address,setAddress]=useState<Address>(initialAddress); const [selected,setSelected]=useState(''); const [validating,setValidating]=useState(false); const [processing,setProcessing]=useState(false); const [query,setQuery]=useState(''); const [suggestions,setSuggestions]=useState<string[]>([]); const [searchParams]=useSearchParams(); const navigate=useNavigate(); const items=ctx.cart.items.map(item=>({item,product:ctx.catalog.find(p=>p.id===item.productId)})).filter((entry):entry is {item:{productId:string;quantity:number};product:Product}=>Boolean(entry.product)); const subtotal=items.reduce((sum,{item,product})=>sum+salePrice(product.price,product.discount)*item.quantity,0); const [coupon,setCoupon]=useState<Coupon|null>(null); useEffect(()=>{if(ctx.user)void listAddresses(ctx.user.id).then(setAddresses).catch((err:any)=>ctx.notify('error','Could not load addresses',err?.message));if(ctx.cart.couponCode)void getCoupon(ctx.cart.couponCode).then(setCoupon)},[ctx.user,ctx.cart.couponCode,ctx.notify]); useEffect(()=>{const sessionId=searchParams.get('session_id');if(!sessionId||!ctx.user)return;void (async()=>{try{const verified=await window.genmb.billing.verifySession(sessionId);const pending=await window.genmb.kv.get(`user:${ctx.user!.id}:pending-checkout`);if(!verified.paid||!pending||pending.sessionId===sessionId)return;const order:Order={...pending.order,paymentSessionId:sessionId,status:'Paid'};const reserved=await Promise.all(order.items.map(async(item)=>({ item, product: await getProduct(item.productId) })));if(reserved.some(({item,product})=>!product||product.stock<item.quantity)) throw new Error('One or more paid items are no longer in stock. Please contact support with your payment confirmation.');await Promise.all(reserved.map(({item,product})=>saveProduct({...(product as Product),stock:(product as Product).stock-item.quantity})));await saveOrder(order);await ctx.refreshCatalog();await saveCart(ctx.user!.id,{items:[]});await window.genmb.kv.delete(`user:${ctx.user!.id}:pending-checkout`);await ctx.refreshCart();ctx.notify('success','Order confirmed',`Order ${order.id.slice(0,8)} is now being prepared.`);navigate(`/orders/${order.id}`,{replace:true})}catch(err:any){ctx.notify('error','Could not confirm payment',err?.message)}})()},[searchParams,ctx.user,ctx, navigate]); const discount=coupon&&subtotal>=coupon.minSpend?subtotal*coupon.percent/100:0; const total=Math.round((subtotal-discount)*100)/100; const selectAddress=(id:string)=>{setSelected(id);const found=addresses.find(a=>a.id===id);if(found){const {id:_,...rest}=found;setAddress(rest)}}; const autocomplete=async(value:string)=>{setQuery(value);if(value.trim().length<4){setSuggestions([]);return}try{const result=await window.genmb.address.autocomplete(value);setSuggestions(result.results.map(r=>r.description))}catch(err:any){ctx.notify('error','Address suggestions unavailable',err?.message)}}; const pay=async(e:React.FormEvent)=>{e.preventDefault();if(!ctx.user||!items.length)return;setValidating(true);try{const result=await window.genmb.address.validate(address);if(!result.valid){ctx.notify('error','Please check your delivery address',result.suggestions?.length?'Choose a corrected address or update the highlighted details.':'Enter a complete street address, city, state, and postal code.');return}const normalized=result.normalized??address;const addressWithId={...normalized,id:selected||crypto.randomUUID()};await saveAddress(ctx.user.id,addressWithId);setAddresses((list)=>list.some(item=>item.id===addressWithId.id)?list.map(item=>item.id===addressWithId.id?addressWithId:item):[addressWithId,...list]);const order:Order={id:crypto.randomUUID(),userId:ctx.user.id,email:ctx.user.email,items:ctx.cart.items,address:normalized,subtotal,discount,total,couponCode:coupon?.code,status:'Processing',createdAt:new Date().toISOString(),paymentSessionId:''};const pending={sessionId:'pending',order};await window.genmb.kv.set(`user:${ctx.user.id}:pending-checkout`,pending);setProcessing(true);const successUrl=`${window.location.origin}${window.location.pathname}#/checkout?session_id={CHECKOUT_SESSION_ID}`;await window.genmb.billing.checkout({amount:total,currency:'usd',productName:`GrowthGenie order ${order.id.slice(0,8)}`,successUrl,cancelUrl:`${window.location.origin}${window.location.pathname}#/checkout`,endUserEmail:ctx.user.email,metadata:{orderId:order.id,userId:ctx.user.id}})}catch(err:any){ctx.notify('error',err?.code==='CONNECT_REQUIRED'?'Payments are temporarily paused':'Checkout could not start',err?.code==='CONNECT_REQUIRED'?'Please check back soon.':err?.message)}finally{setValidating(false);setProcessing(false)}}; if(!ctx.user)return <Shell ctx={ctx}><div className="mx-auto max-w-4xl px-4 py-12 sm:px-6"><EmptyState icon={<LogIn size={28}/>} title="Sign in to check out" description="We need your secure account before creating an order and saving your delivery address." action={<Link to="/login"><Button>Sign in securely</Button></Link>}/></div></Shell>; if(!items.length)return <Shell ctx={ctx}><div className="mx-auto max-w-4xl px-4 py-12 sm:px-6"><EmptyState icon={<ShoppingBag size={28}/>} title="Your cart is empty" description="Add an item before moving to secure checkout." action={<Link to="/shop"><Button>Shop products</Button></Link>}/></div></Shell>; return <Shell ctx={ctx}><section className="mx-auto max-w-6xl px-4 py-10 sm:px-6"><h1 className="text-4xl font-bold">Secure checkout</h1><p className="mt-2 text-muted-foreground">Your payment is processed by Stripe via GenMB. We confirm payment before creating your order.</p><form onSubmit={pay} className="mt-8 grid gap-6 lg:grid-cols-[1fr_340px]"><div className="rounded-lg border bg-card p-6 shadow-sm"><h2 className="text-xl font-bold">Delivery address</h2>{addresses.length>0&&<SelectField label="Saved address" value={selected} onChange={(e)=>selectAddress(e.target.value)} className="mt-5"><option value="">Use a new address</option>{addresses.map(item=><option key={item.id} value={item.id}>{window.genmb.address.format(item)}</option>)}</SelectField>}<div className="mt-5 grid gap-4 sm:grid-cols-2"><Field label="Street address" value={address.line1} onChange={(e)=>{setAddress({...address,line1:e.target.value});void autocomplete(e.target.value)}} required/><Field label="Apartment, suite, etc. (optional)" value={address.line2??''} onChange={(e)=>setAddress({...address,line2:e.target.value})} /></div>{suggestions.length>0&&<div className="mt-2 rounded-lg border bg-popover p-2 text-sm shadow-md"><p className="px-2 py-1 text-muted-foreground">Address suggestions</p>{suggestions.map((item)=><button key={item} type="button" onClick={()=>{setAddress({...address,line1:item});setSuggestions([])}} className="block w-full rounded px-2 py-2 text-left hover:bg-accent">{item}</button>)}</div>}<div className="mt-4 grid gap-4 sm:grid-cols-3"><Field label="City" value={address.city} onChange={(e)=>setAddress({...address,city:e.target.value})} required/><Field label="State / region" value={address.region} onChange={(e)=>setAddress({...address,region:e.target.value})} required/><Field label="Postal code" value={address.postalCode} onChange={(e)=>setAddress({...address,postalCode:e.target.value})} required/></div><div className="mt-4 grid gap-4 sm:grid-cols-2"><Field label="Country" value={address.country} onChange={(e)=>setAddress({...address,country:e.target.value})} required/><Field label="Country code" value={address.countryCode} onChange={(e)=>setAddress({...address,countryCode:e.target.value.toUpperCase()})} required/></div><p className="mt-5 flex items-center gap-2 rounded-lg bg-muted p-3 text-sm text-muted-foreground"><ShieldCheck size={17} className="text-primary"/> Your address is validated before payment and saved only to your secure account.</p></div><aside className="h-fit rounded-lg border bg-card p-5 shadow-sm"><h2 className="font-bold">Order summary</h2><div className="mt-4 space-y-3 text-sm">{items.map(({item,product})=><div key={product.id} className="flex gap-2"><span className="grid size-6 shrink-0 place-items-center rounded bg-muted text-xs font-bold">{item.quantity}</span><span className="min-w-0 flex-1 truncate">{product.name}</span><span>{money(salePrice(product.price,product.discount)*item.quantity)}</span></div>)}</div><div className="mt-5 space-y-2 border-t pt-4 text-sm"><div className="flex justify-between"><span className="text-muted-foreground">Subtotal</span><span>{money(subtotal)}</span></div><div className="flex justify-between"><span className="text-muted-foreground">Coupon discount</span><span className="text-primary">−{money(discount)}</span></div><div className="flex justify-between pt-2 text-base font-bold"><span>Total</span><span>{money(total)}</span></div></div><Button type="submit" className="mt-5 w-full" loading={processing||validating} disabled={processing||validating}>Pay {money(total)} securely</Button><p className="mt-3 text-center text-xs text-muted-foreground">You will be redirected to Stripe Checkout. Payment is verified before your order is created.</p></aside></form></section></Shell> }

function OrdersPage({ctx}:{ctx:AppContext}) { useDocument('Your Orders | GrowthGenie AI','Track paid orders and review delivery details from your secure GrowthGenie account.'); const [orders,setOrders]=useState<Order[]>([]); const [loading,setLoading]=useState(Boolean(ctx.user)); const load=useCallback(async()=>{if(!ctx.user)return;setLoading(true);try{setOrders(await listOrders(ctx.user.id))}catch(err:any){ctx.notify('error','Could not load orders',err?.message)}finally{setLoading(false)}},[ctx.user,ctx.notify]);useEffect(()=>{void load()},[load]);if(!ctx.user)return <Shell ctx={ctx}><div className="mx-auto max-w-4xl px-4 py-12 sm:px-6"><EmptyState icon={<LogIn size={28}/>} title="Sign in to see your orders" description="Your order history and delivery updates are kept in your secure account." action={<Link to="/login"><Button>Sign in</Button></Link>}/></div></Shell>;return <Shell ctx={ctx}><section className="mx-auto max-w-6xl px-4 py-10 sm:px-6"><h1 className="text-4xl font-bold">Your orders</h1><p className="mt-2 text-muted-foreground">Track every confirmed GrowthGenie order in one place.</p><div className="mt-8">{loading?<div className="space-y-3">{[1,2,3].map(i=><div key={i} className="h-28 animate-pulse rounded-lg bg-muted"/>)}</div>:orders.length?<div className="overflow-hidden rounded-lg border bg-card shadow-sm"><div className="hidden grid-cols-[1.2fr_1fr_1fr_1fr_auto] bg-muted px-4 py-3 text-xs font-bold uppercase tracking-wide text-muted-foreground md:grid"><span>Order</span><span>Date</span><span>Status</span><span className="text-right">Total</span><span/></div>{orders.map(order=><div key={order.id} className="grid gap-2 border-t px-4 py-4 text-sm md:grid-cols-[1.2fr_1fr_1fr_1fr_auto] md:items-center"><span className="font-semibold">#{order.id.slice(0,8).toUpperCase()}</span><span className="text-muted-foreground">{dateLabel(order.createdAt)}</span><span><StatusBadge status={order.status}/></span><span className="font-bold md:text-right">{money(order.total)}</span><Link to={`/orders/${order.id}`} className="font-semibold text-primary hover:underline">Details</Link></div>)}</div>:<EmptyState icon={<ClipboardList size={28}/>} title="No confirmed orders yet" description="When your Stripe payment is verified, your order and delivery status will appear here." action={<Link to="/shop"><Button>Start shopping</Button></Link>}/>}</div></section></Shell> }
function StatusBadge({status}:{status:OrderStatus}){const styles:Record<OrderStatus,string>={Processing:'bg-muted text-muted-foreground',Paid:'bg-accent text-primary',Packed:'bg-accent text-primary',Shipped:'bg-accent text-primary',Delivered:'bg-accent text-primary',Cancelled:'bg-destructive/10 text-destructive'};return <span className={cn('inline-flex rounded-full px-2.5 py-1 text-xs font-bold',styles[status])}>{status}</span>}
function OrderDetailPage({ctx}:{ctx:AppContext}) { const {id=''}=useParams();const [order,setOrder]=useState<Order|null>(null);const [loading,setLoading]=useState(true);useDocument('Order Details | GrowthGenie AI','View your order items, payment status, delivery address, and shipment progress.');useEffect(()=>{if(!ctx.user)return;void (async()=>{try{setOrder(await (await import('./lib/store')).getOrder(ctx.user!.id,id))}catch(err:any){ctx.notify('error','Could not load order',err?.message)}finally{setLoading(false)}})()},[ctx.user,id,ctx.notify]);if(!ctx.user)return <Navigate to="/login" replace/>;if(loading)return <Shell ctx={ctx}><div className="mx-auto max-w-5xl px-4 py-12 sm:px-6"><div className="h-72 animate-pulse rounded-lg bg-muted"/></div></Shell>;if(!order)return <Shell ctx={ctx}><div className="mx-auto max-w-5xl px-4 py-12 sm:px-6"><EmptyState title="Order not found" description="This order may not belong to your account." action={<Link to="/orders"><Button>Back to orders</Button></Link>}/></div></Shell>;const stages: Array<'Paid'|'Packed'|'Shipped'|'Delivered'>=['Paid','Packed','Shipped','Delivered'];const current=Math.max(0,stages.indexOf(order.status as any));return <Shell ctx={ctx}><section className="mx-auto max-w-5xl px-4 py-10 sm:px-6"><Link to="/orders" className="text-sm font-semibold text-primary hover:underline">← All orders</Link><div className="mt-4 flex flex-wrap items-end justify-between gap-3"><div><p className="text-sm text-muted-foreground">Order #{order.id.slice(0,8).toUpperCase()}</p><h1 className="text-4xl font-bold">Order details</h1></div><StatusBadge status={order.status}/></div><div className="mt-8 rounded-lg border bg-card p-5 shadow-sm"><h2 className="font-bold">Delivery progress</h2><div className="mt-6 grid grid-cols-4 gap-2">{stages.map((stage,index)=><div key={stage} className="text-center"><div className={cn('mx-auto grid size-8 place-items-center rounded-full text-xs font-bold',index<=current?'bg-primary text-primary-foreground':'bg-muted text-muted-foreground')}>{index<=current?<Check size={15}/>:index+1}</div><p className="mt-2 text-xs font-semibold">{stage}</p></div>)}</div></div><div className="mt-6 grid gap-6 lg:grid-cols-[1fr_.7fr]"><div className="rounded-lg border bg-card shadow-sm"><h2 className="border-b p-5 font-bold">Items</h2>{order.items.map(item=>{const product=ctx.catalog.find(p=>p.id===item.productId);return <div key={item.productId} className="flex gap-3 border-b p-4 last:border-0"><img data-genmb-img={product?.name??'Ordered product'} src={product?.image??`https://picsum.photos/seed/${item.productId}/120/120`} alt={product?.name??'Ordered product'} width="80" height="80" className="size-16 rounded object-cover bg-muted"/><div className="flex-1"><p className="font-semibold">{product?.name??item.productId}</p><p className="text-sm text-muted-foreground">Qty {item.quantity}</p></div><p className="font-bold">{product?money(salePrice(product.price,product.discount)*item.quantity):''}</p></div>})}</div><div className="space-y-5"><article className="rounded-lg border bg-card p-5 shadow-sm"><h2 className="font-bold">Ship to</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">{window.genmb.address.format(order.address)}</p></article><article className="rounded-lg border bg-card p-5 shadow-sm"><h2 className="font-bold">Payment</h2><div className="mt-3 flex justify-between text-sm"><span className="text-muted-foreground">Paid securely</span><span className="font-bold">{money(order.total)}</span></div><div className="mt-2 flex justify-between text-sm"><span className="text-muted-foreground">Order date</span><span>{dateLabel(order.createdAt)}</span></div></article></div></div></section></Shell> }

function ProfilePage({ctx}:{ctx:AppContext}) { useDocument('Your Profile | GrowthGenie AI','Manage your GrowthGenie shopping preferences and securely saved delivery addresses.'); const [name,setName]=useState(ctx.profile?.name??'');const [preferences,setPreferences]=useState(ctx.profile?.preferences.join(', ')??'');const [saving,setSaving]=useState(false);const [addresses,setAddresses]=useState<Array<Address & {id:string}>>([]);useEffect(()=>{setName(ctx.profile?.name??'');setPreferences(ctx.profile?.preferences.join(', ')??'')},[ctx.profile]);useEffect(()=>{if(ctx.user)void listAddresses(ctx.user.id).then(setAddresses).catch((err:any)=>ctx.notify('error','Could not load addresses',err?.message))},[ctx.user,ctx.notify]);const save=async(e:React.FormEvent)=>{e.preventDefault();if(!ctx.profile)return;setSaving(true);try{const next={...ctx.profile,name:name.trim()||ctx.profile.name,preferences:preferences.split(',').map(x=>x.trim()).filter(Boolean)};await saveProfile(next);ctx.updateProfile(next);ctx.notify('success','Profile saved','Your preferences help the AI concierge tailor recommendations.')}catch(err:any){ctx.notify('error','Could not save profile',err?.message)}finally{setSaving(false)}};const removeAddress=async(id:string)=>{if(!ctx.user)return;try{await (await import('./lib/store')).deleteAddress(ctx.user.id,id);setAddresses(list=>list.filter(item=>item.id!==id));ctx.notify('success','Address removed')}catch(err:any){ctx.notify('error','Could not remove address',err?.message)}};if(!ctx.user)return <Navigate to="/login" replace/>;return <Shell ctx={ctx}><section className="mx-auto max-w-5xl px-4 py-10 sm:px-6"><h1 className="text-4xl font-bold">Your profile</h1><p className="mt-2 text-muted-foreground">Refine what the concierge knows about your preferences.</p><div className="mt-8 grid gap-6 lg:grid-cols-2"><form onSubmit={save} className="rounded-lg border bg-card p-6 shadow-sm"><h2 className="text-xl font-bold">Shopping profile</h2><div className="mt-5 grid gap-4"><Field label="Name" value={name} onChange={(e)=>setName(e.target.value)} onBlur={()=>!name.trim()&&ctx.notify('info','Add your name','A name helps personalize your account.')} required/><Field label="Email" value={ctx.user.email} disabled/><Field label="Preferences" value={preferences} onChange={(e)=>setPreferences(e.target.value)} placeholder="travel, sustainable, running"/><p className="text-xs text-muted-foreground">Separate preferences with commas. The AI agent uses these as additional signals for recommendations.</p><Button type="submit" loading={saving}>Save profile</Button></div></form><section className="rounded-lg border bg-card p-6 shadow-sm"><h2 className="text-xl font-bold">Saved addresses</h2>{addresses.length?<div className="mt-5 grid gap-3">{addresses.map(address=><article key={address.id} className="rounded-lg border p-4"><p className="text-sm leading-6 text-muted-foreground">{window.genmb.address.format(address)}</p><button onClick={()=>removeAddress(address.id)} className="mt-3 text-sm font-semibold text-destructive hover:underline">Remove address</button></article>)}</div>:<div className="mt-5"><EmptyState icon={<Home size={24}/>} title="No saved addresses" description="Your delivery address is saved after an address-validated checkout." action={<Link to="/shop"><Button variant="outline">Keep shopping</Button></Link>}/></div>}</section></div></section></Shell> }

function LoginPage({ctx}:{ctx:AppContext}) { useDocument('Sign In | GrowthGenie AI','Sign in securely to save your cart, wishlist, profile, conversations, and order history.'); const navigate=useNavigate();const [mode,setMode]=useState<'signin'|'signup'|'magic'|'reset'>('signin');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [name,setName]=useState('');const [code,setCode]=useState('');const [pending,setPending]=useState(false);const [awaitingCode,setAwaitingCode]=useState(false);useEffect(()=>{if(ctx.user)navigate('/')},[ctx.user,navigate]);const submit=async(e:React.FormEvent)=>{e.preventDefault();setPending(true);try{if(mode==='signin'){const user=await window.genmb.auth.signInWithPassword(email,password);if(!user)ctx.notify('info','Sign-in cancelled');else ctx.notify('success','Welcome back',user.name||user.email)}else if(mode==='signup'){if(awaitingCode){const user=await window.genmb.auth.verifySignUp(email,code);if(user)ctx.notify('success','Account verified','Welcome to GrowthGenie.')}else{await window.genmb.auth.signUp(email,password,name);setAwaitingCode(true);ctx.notify('info','Check your email','Enter the 6-digit code we sent to finish creating your account.')}}else if(mode==='magic'){await window.genmb.auth.sendMagicLink(email);ctx.notify('info','Check your email','We sent a secure sign-in link.')}else{if(awaitingCode){await window.genmb.auth.confirmPasswordReset(email,code,password);setAwaitingCode(false);setMode('signin');ctx.notify('success','Password updated','You can now sign in with your new password.')}else{await window.genmb.auth.requestPasswordReset(email);setAwaitingCode(true);ctx.notify('info','Check your email','Enter the reset code and your new password.')}}}catch(err:any){ctx.notify('error','Authentication failed',err?.message)}finally{setPending(false)}};const google=async()=>{setPending(true);try{const user=await window.genmb.auth.signIn();if(user)ctx.notify('success','Welcome to GrowthGenie',user.name||user.email)}catch(err:any){ctx.notify('error','Google sign-in failed',err?.message)}finally{setPending(false)}};const changeMode=(next:typeof mode)=>{setMode(next);setAwaitingCode(false);setCode('');setPassword('')};return <div className="min-h-screen bg-muted/50"><header className="mx-auto flex max-w-6xl items-center justify-between px-4 py-6 sm:px-6"><Link to="/" className="flex items-center gap-2 font-bold"><span className="grid size-9 place-items-center rounded-lg bg-primary text-primary-foreground"><Sparkles size={18}/></span>Growth<span className="-ml-2 text-primary">Genie</span></Link><Link to="/shop" className="text-sm font-semibold text-primary hover:underline">Continue as guest</Link></header><main className="mx-auto grid max-w-6xl items-center gap-10 px-4 py-8 sm:px-6 lg:grid-cols-2"><section className="hidden lg:block"><p className="text-sm font-semibold uppercase tracking-[.14em] text-primary">A better way to shop</p><h2 className="mt-3 text-5xl font-black leading-tight">Save your shopping journey.</h2><p className="mt-5 max-w-md text-lg leading-8 text-muted-foreground">Keep your AI recommendations, wishlist, cart, validated addresses, and paid orders together under one secure account.</p></section><section className="rounded-lg border bg-card p-6 shadow-sm sm:p-8"><h1 className="text-2xl font-bold">{mode==='signup'?'Create your account':mode==='magic'?'Sign in with email link':mode==='reset'?'Reset your password':'Welcome back'}</h1><p className="mt-2 text-sm text-muted-foreground">{mode==='signup'?'Create a secure account to save your commerce journey.':'Your account keeps carts, favorites, and orders in sync.'}</p><form onSubmit={submit} className="mt-6 grid gap-4">{mode==='signup'&&!awaitingCode&&<Field label="Name" value={name} onChange={(e)=>setName(e.target.value)} required/>}<Field label="Email" type="email" value={email} onChange={(e)=>setEmail(e.target.value)} required disabled={awaitingCode}/>{(mode==='signin'||mode==='signup'||mode==='reset')&&!awaitingCode&&<Field label="Password" type="password" minLength={8} value={password} onChange={(e)=>setPassword(e.target.value)} required/>}{awaitingCode&&<><Field label="6-digit code" inputMode="numeric" pattern="[0-9]{6}" value={code} onChange={(e)=>setCode(e.target.value)} required/>{mode==='reset'&&<Field label="New password" type="password" minLength={8} value={password} onChange={(e)=>setPassword(e.target.value)} required/>}</>}<Button type="submit" loading={pending}>{awaitingCode?'Verify code':mode==='signup'?'Create account':mode==='magic'?'Send secure link':mode==='reset'?'Send reset code':'Sign in'}</Button></form>{mode!=='magic'&&!awaitingCode&&<><div className="my-5 flex items-center gap-3 text-xs text-muted-foreground before:h-px before:flex-1 before:bg-border after:h-px after:flex-1 after:bg-border">OR</div><Button className="w-full" variant="outline" onClick={google} loading={pending}>Continue with Google</Button></>}<div className="mt-6 flex flex-wrap gap-x-4 gap-y-2 text-sm font-semibold"><button onClick={()=>changeMode(mode==='signin'?'signup':'signin')} className="text-primary hover:underline">{mode==='signin'?'Create account':'Sign in instead'}</button><button onClick={()=>changeMode('magic')} className="text-primary hover:underline">Email link</button>{mode==='signin'&&<button onClick={()=>changeMode('reset')} className="text-primary hover:underline">Forgot password?</button>}</div><p className="mt-5 text-xs text-muted-foreground">For the admin dashboard, sign in with the authorized account <strong>{ADMIN_EMAIL}</strong>.</p></section></main></div> }

function AdminPage({ctx}:{ctx:AppContext}) { useDocument('Admin Dashboard | GrowthGenie AI','Manage GrowthGenie catalog inventory, customers, orders, sales, and product performance.'); const [tab,setTab]=useState<'overview'|'products'|'orders'|'users'>('overview');const [orders,setOrders]=useState<Order[]>([]);const [users,setUsers]=useState<UserProfile[]>([]);const [editing,setEditing]=useState<Product|null>(null);const [selectedOrder,setSelectedOrder]=useState<Order|null>(null);const [search,setSearch]=useState('');const [inventoryCategory,setInventoryCategory]=useState('All');const [inventorySort,setInventorySort]=useState('newest');const [loading,setLoading]=useState(false);const load=useCallback(async()=>{setLoading(true);try{const [allOrders,allUsers]=await Promise.all([listOrders(),listProfiles()]);setOrders(allOrders);setUsers(allUsers)}catch(err:any){ctx.notify('error','Could not load admin data',err?.message)}finally{setLoading(false)}},[ctx.notify]);useEffect(()=>{if(ctx.profile?.role==='admin')void load()},[ctx.profile?.role,load]);if(ctx.loading)return <Shell ctx={ctx}><div className="mx-auto max-w-7xl px-4 py-12 sm:px-6"><div className="h-80 animate-pulse rounded-lg bg-muted"/></div></Shell>;if(!ctx.user)return <Navigate to="/login" replace/>;if(ctx.profile?.role!=='admin')return <Shell ctx={ctx}><div className="mx-auto max-w-4xl px-4 py-12 sm:px-6"><EmptyState icon={<ShieldCheck size={28}/>} title="Admin access required" description="This dashboard is protected. Sign in using the authorized GrowthGenie administrator account to continue." action={<Link to="/profile"><Button>Back to profile</Button></Link>}/></div></Shell>;const revenue=orders.filter(o=>o.status!=='Cancelled').reduce((sum,o)=>sum+o.total,0);const dailySales=Array.from({length:7},(_,index)=>{const day=new Date();day.setHours(0,0,0,0);day.setDate(day.getDate()-(6-index));const nextDay=new Date(day);nextDay.setDate(day.getDate()+1);return {label:new Intl.DateTimeFormat('en-US',{weekday:'short'}).format(day).slice(0,1),total:orders.filter(order=>order.status!=='Cancelled'&&Date.parse(order.createdAt)>=day.getTime()&&Date.parse(order.createdAt)<nextDay.getTime()).reduce((sum,order)=>sum+order.total,0)}});const maxDailySales=Math.max(...dailySales.map(day=>day.total),1);const inventoryCategories=['All',...Array.from(new Set(ctx.catalog.map(product=>product.category)))];const filtered=ctx.catalog.filter(product=>[product.name,product.brand,product.category].join(' ').toLowerCase().includes(search.toLowerCase())&&(inventoryCategory==='All'||product.category===inventoryCategory)).sort((a,b)=>inventorySort==='price-low'?salePrice(a.price,a.discount)-salePrice(b.price,b.discount):inventorySort==='price-high'?salePrice(b.price,b.discount)-salePrice(a.price,a.discount):inventorySort==='rating'?b.rating-a.rating:inventorySort==='stock'?a.stock-b.stock:Date.parse(b.createdAt)-Date.parse(a.createdAt));const save=async(product:Product)=>{try{await saveProduct(product);await ctx.refreshCatalog();setEditing(null);ctx.notify('success','Product saved',product.name)}catch(err:any){ctx.notify('error','Could not save product',err?.message)}};const remove=async(product:Product)=>{try{await removeProduct(product.id);await ctx.refreshCatalog();ctx.notify('success','Product deleted',product.name)}catch(err:any){ctx.notify('error','Could not delete product',err?.message)}};const setStatus=async(order:Order,status:OrderStatus)=>{try{const next={...order,status};await updateOrder(next);setOrders(list=>list.map(item=>item.id===next.id?next:item));ctx.notify('success','Order status updated',`${next.id.slice(0,8)} is now ${status}.`)}catch(err:any){ctx.notify('error','Could not update order',err?.message)}};return <Shell ctx={ctx}><section className="mx-auto max-w-7xl px-4 py-10 sm:px-6"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-sm font-semibold uppercase tracking-[.14em] text-primary">Admin console</p><h1 className="mt-2 text-4xl font-bold">Commerce command center</h1></div><Button variant="outline" onClick={load} loading={loading}>Refresh data</Button></div><div className="mt-7 flex gap-1 overflow-x-auto rounded-lg border bg-card p-1">{([{id:'overview',label:'Overview',icon:LayoutDashboard},{id:'products',label:'Products',icon:Package},{id:'orders',label:'Orders',icon:ClipboardList},{id:'users',label:'Users',icon:Users}] as const).map(({id,label,icon:Icon})=><button key={id} onClick={()=>setTab(id)} className={cn('inline-flex shrink-0 items-center gap-2 rounded-md px-4 py-2 text-sm font-semibold transition hover:bg-accent',tab===id&&'bg-accent text-primary')}><Icon size={16}/>{label}</button>)}</div>{tab==='overview'&&<div className="mt-7"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Metric title="Catalog products" value={String(ctx.catalog.length)} icon={<Package size={20}/>}/><Metric title="Registered users" value={String(users.length)} icon={<Users size={20}/>}/><Metric title="Confirmed orders" value={String(orders.length)} icon={<ClipboardList size={20}/>}/><Metric title="Revenue" value={money(revenue)} icon={<BarChart3 size={20}/>}/></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><section className="rounded-lg border bg-card p-6 shadow-sm"><h2 className="text-lg font-bold">Sales performance</h2><p className="mt-1 text-sm text-muted-foreground">Revenue from verified, non-cancelled orders.</p><div className="mt-7 flex items-end gap-3">{dailySales.map((day,index)=><div key={`${day.label}-${index}`} className="flex flex-1 flex-col items-center gap-2"><div className="w-full rounded-t bg-primary/80" style={{height:`${Math.max(4,Math.round(day.total/maxDailySales*96))}px`}} title={`${day.label}: ${money(day.total)}`}/><span className="text-xs text-muted-foreground">{day.label}</span></div>)}</div></section><section className="rounded-lg border bg-card p-6 shadow-sm"><h2 className="text-lg font-bold">Top product performance</h2><div className="mt-5 space-y-4">{[...ctx.catalog].sort((a,b)=>b.popularity-a.popularity).slice(0,5).map(product=><div key={product.id} className="flex items-center gap-3"><img data-genmb-img={product.name} src={product.image} alt={product.name} width="44" height="44" className="size-11 rounded object-cover bg-muted"/><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{product.name}</p><p className="text-xs text-muted-foreground">Popularity score {product.popularity}</p></div><Stars rating={product.rating}/></div>)}</div></section></div></div>}{tab==='products'&&<section className="mt-7"><div className="mb-5 flex flex-wrap items-end justify-between gap-3"><Field label="Search inventory" value={search} onChange={(e)=>setSearch(e.target.value)} placeholder="Product, brand, category" className="w-full sm:w-64"/><SelectField label="Category filter" value={inventoryCategory} onChange={(e)=>setInventoryCategory(e.target.value)} className="w-44">{inventoryCategories.map(category=><option key={category}>{category}</option>)}</SelectField><SelectField label="Sort inventory" value={inventorySort} onChange={(e)=>setInventorySort(e.target.value)} className="w-44"><option value="newest">Newest</option><option value="price-low">Price: low first</option><option value="price-high">Price: high first</option><option value="rating">Highest rating</option><option value="stock">Lowest stock</option></SelectField><Button onClick={()=>setEditing({id:crypto.randomUUID(),name:'',description:'',category:'Electronics',price:0,discount:0,stock:0,rating:4.5,reviewCount:0,image:'https://picsum.photos/seed/new-growthgenie-product/800/800',brand:'',tags:[],popularity:0,createdAt:new Date().toISOString()})}>Add product</Button></div><div className="overflow-x-auto rounded-lg border bg-card shadow-sm"><table className="w-full min-w-200 text-sm"><thead className="sticky top-0 bg-muted text-left text-xs uppercase tracking-wide text-muted-foreground"><tr><th className="px-4 py-3">Product</th><th className="px-4 py-3">Category</th><th className="px-4 py-3 text-right">Price</th><th className="px-4 py-3 text-right">Stock</th><th className="px-4 py-3 text-right">Rating</th><th className="px-4 py-3">Actions</th></tr></thead><tbody>{filtered.map(product=><tr key={product.id} className="border-t hover:bg-muted/50"><td className="px-4 py-3"><div className="flex items-center gap-3"><img data-genmb-img={product.name} src={product.image} alt={product.name} width="40" height="40" className="size-10 rounded object-cover bg-muted"/><span className="font-semibold">{product.name}</span></div></td><td className="px-4 py-3">{product.category}</td><td className="px-4 py-3 text-right">{money(salePrice(product.price,product.discount))}</td><td className={cn('px-4 py-3 text-right font-semibold',product.stock<10&&'text-destructive')}>{product.stock}</td><td className="px-4 py-3 text-right">{product.rating}</td><td className="px-4 py-3"><div className="flex gap-3"><button onClick={()=>setEditing(product)} className="font-semibold text-primary hover:underline">Edit</button><button onClick={()=>remove(product)} className="font-semibold text-destructive hover:underline">Delete</button></div></td></tr>)}</tbody></table>{!filtered.length&&<EmptyState title="No inventory matches" description="Change the search term to find a product." action={<Button onClick={()=>setSearch('')}>Clear search</Button>}/>}</div></section>}{tab==='orders'&&<section className="mt-7 overflow-x-auto rounded-lg border bg-card shadow-sm"><table className="w-full min-w-180 text-sm"><thead className="bg-muted text-left text-xs uppercase tracking-wide text-muted-foreground"><tr><th className="px-4 py-3">Order</th><th className="px-4 py-3">Customer</th><th className="px-4 py-3">Date</th><th className="px-4 py-3 text-right">Total</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Details</th></tr></thead><tbody>{orders.map(order=><tr key={order.id} className="border-t hover:bg-muted/50"><td className="px-4 py-3 font-semibold">#{order.id.slice(0,8).toUpperCase()}</td><td className="px-4 py-3">{order.email}</td><td className="px-4 py-3">{dateLabel(order.createdAt)}</td><td className="px-4 py-3 text-right">{money(order.total)}</td><td className="px-4 py-3"><select aria-label={`Set order ${order.id.slice(0,8)} status`} value={order.status} onChange={(e)=>setStatus(order,e.target.value as OrderStatus)} className="rounded border bg-card px-2 py-1 text-sm focus:ring-2 focus:ring-ring">{(['Processing','Paid','Packed','Shipped','Delivered','Cancelled'] as OrderStatus[]).map(status=><option key={status}>{status}</option>)}</select></td><td className="px-4 py-3"><button onClick={()=>setSelectedOrder(order)} className="font-semibold text-primary hover:underline">View</button></td></tr>)}</tbody></table>{!orders.length&&<EmptyState icon={<ClipboardList size={28}/>} title="No orders to manage" description="Verified customer payments will appear here automatically."/>}</section>}{tab==='users'&&<section className="mt-7 overflow-x-auto rounded-lg border bg-card shadow-sm"><table className="w-full min-w-150 text-sm"><thead className="bg-muted text-left text-xs uppercase tracking-wide text-muted-foreground"><tr><th className="px-4 py-3">Customer</th><th className="px-4 py-3">Role</th><th className="px-4 py-3">Joined</th><th className="px-4 py-3">Preferences</th></tr></thead><tbody>{users.map(user=><tr key={user.id} className="border-t hover:bg-muted/50"><td className="px-4 py-3"><p className="font-semibold">{user.name}</p><p className="text-xs text-muted-foreground">{user.email}</p></td><td className="px-4 py-3"><span className="rounded-full bg-accent px-2 py-1 text-xs font-bold text-primary">{user.role}</span></td><td className="px-4 py-3">{dateLabel(user.joinedAt)}</td><td className="px-4 py-3 text-muted-foreground">{user.preferences.join(', ')||'—'}</td></tr>)}</tbody></table>{!users.length&&<EmptyState icon={<Users size={28}/>} title="No customer profiles yet" description="Profiles are created automatically when authenticated shoppers first visit GrowthGenie."/>}</section>}<ProductEditor product={editing} onClose={()=>setEditing(null)} onSave={save}/><Modal open={Boolean(selectedOrder)} onClose={()=>setSelectedOrder(null)} title="Order details">{selectedOrder&&<div className="grid gap-5 text-sm"><div className="rounded-lg bg-muted p-4"><p className="font-bold">#{selectedOrder.id.slice(0,8).toUpperCase()} · {selectedOrder.email}</p><p className="mt-1 text-muted-foreground">Placed {dateLabel(selectedOrder.createdAt)} · {money(selectedOrder.total)} · {selectedOrder.status}</p></div><div><h3 className="font-bold">Items</h3><div className="mt-3 grid gap-2">{selectedOrder.items.map(item=>{const product=ctx.catalog.find(candidate=>candidate.id===item.productId);return <div key={item.productId} className="flex justify-between rounded-lg border p-3"><span>{product?.name??item.productId} × {item.quantity}</span><span className="font-semibold">{product?money(salePrice(product.price,product.discount)*item.quantity):'—'}</span></div>})}</div></div><div><h3 className="font-bold">Delivery address</h3><p className="mt-1 leading-6 text-muted-foreground">{window.genmb.address.format(selectedOrder.address)}</p></div></div>}</Modal></section></Shell> }
function Metric({title,value,icon}:{title:string;value:string;icon:React.ReactNode}){return <article className="rounded-lg border bg-card p-5 shadow-sm"><div className="flex items-center justify-between text-muted-foreground"><p className="text-sm font-semibold">{title}</p><span>{icon}</span></div><p className="mt-3 text-3xl font-bold">{value}</p></article>}
function ProductEditor({product,onClose,onSave}:{product:Product|null;onClose:()=>void;onSave:(product:Product)=>Promise<void>}){const [draft,setDraft]=useState<Product|null>(product);const [saving,setSaving]=useState(false);useEffect(()=>setDraft(product),[product]);if(!draft)return null;const update=<K extends keyof Product>(key:K,value:Product[K])=>setDraft(current=>current?{...current,[key]:value}:current);const submit=async(e:React.FormEvent)=>{e.preventDefault();if(!draft.name.trim()||!draft.brand.trim()||!draft.description.trim()){return}setSaving(true);try{await onSave({...draft,name:draft.name.trim(),brand:draft.brand.trim(),description:draft.description.trim(),tags:draft.tags.filter(Boolean)})}finally{setSaving(false)}};return <Modal open={Boolean(product)} onClose={onClose} title={product?.name?'Edit product':'Add product'}><form onSubmit={submit} className="grid gap-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Product name" value={draft.name} onChange={(e)=>update('name',e.target.value)} required/><Field label="Brand" value={draft.brand} onChange={(e)=>update('brand',e.target.value)} required/><Field label="Category" value={draft.category} onChange={(e)=>update('category',e.target.value)} required/><Field label="Image URL" type="url" value={draft.image} onChange={(e)=>update('image',e.target.value)} required/><Field label="Price" type="number" min="0" step="0.01" value={draft.price} onChange={(e)=>update('price',Number(e.target.value))} required/><Field label="Discount percent" type="number" min="0" max="100" value={draft.discount} onChange={(e)=>update('discount',Number(e.target.value))} required/><Field label="Stock" type="number" min="0" value={draft.stock} onChange={(e)=>update('stock',Number(e.target.value))} required/><Field label="Rating" type="number" min="0" max="5" step="0.1" value={draft.rating} onChange={(e)=>update('rating',Number(e.target.value))} required/></div><label className="grid gap-1.5 text-sm font-medium">Description<textarea value={draft.description} onChange={(e)=>update('description',e.target.value)} required className="min-h-24 rounded-lg border bg-card p-3 text-sm outline-none focus:ring-2 focus:ring-ring"/></label><Field label="Tags (comma separated)" value={draft.tags.join(', ')} onChange={(e)=>update('tags',e.target.value.split(',').map(x=>x.trim()))}/><div className="flex justify-end gap-3"><Button type="button" variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" loading={saving} disabled={!draft.name.trim()||!draft.brand.trim()||!draft.description.trim()}>Save product</Button></div></form></Modal>}

export default App
